import{_ as t,o,c as i,a2 as a}from"./chunks/framework.DrUzr5Tc.js";const h=JSON.parse('{"title":"Project Pitch: Multi-Project Chat & AI Collaboration Suite","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),n={name:"00b-project-pitch.md"};function r(s,e,c,l,p,d){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="project-pitch-multi-project-chat-ai-collaboration-suite" tabindex="-1">Project Pitch: Multi-Project Chat &amp; AI Collaboration Suite <a class="header-anchor" href="#project-pitch-multi-project-chat-ai-collaboration-suite" aria-label="Permalink to &quot;Project Pitch: Multi-Project Chat &amp; AI Collaboration Suite&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built the <strong>Multi-Project Chat &amp; AI Collaboration Suite</strong>, featuring <strong>Soen</strong>, an in-browser collaborative cloud IDE. Built with React 18, Node.js, Express, Socket.IO, Redis, and MongoDB, Soen integrates Google Gemini AI to generate full-stack applications on the fly and boots a real Node.js runtime directly inside the user&#39;s browser using the WebContainer WebAssembly API. The suite also includes an enterprise messaging portal powered by Tencent TRTC Chat UIKit.&quot;</p><h2 id="_2-minute-spoken-pitch" tabindex="-1">2-Minute Spoken Pitch <a class="header-anchor" href="#_2-minute-spoken-pitch" aria-label="Permalink to &quot;2-Minute Spoken Pitch&quot;">​</a></h2><p>&quot;Setting up local development environments for pair programming or technical interviews is notoriously frustrating—incompatible Node versions, missing dependencies, and port conflicts waste valuable engineering time.</p><p>To solve this, I engineered Soen, an intelligent collaborative development workspace:</p><p>First, for instant execution with zero server compute costs, I integrated the WebContainer API. Soen boots an entire Node.js development server directly inside the user&#39;s browser using WebAssembly. Users can run <code>npm install</code>, start dev servers, and view live interactive web applications with sub-second startup times and zero backend container overhead.</p><p>Second, for AI code synthesis, our backend connects to Google Gemini AI in <code>soen-main/backend</code>. When a developer asks to build an application—such as a real-time counter or REST API—Gemini generates a structured JSON file tree containing complete file paths and code. Our frontend parses this payload and automatically writes the files into the WebContainer virtual filesystem.</p><p>Third, for multi-user collaboration, I built real-time project rooms using Socket.IO. When multiple developers join a project workspace, file changes, cursor selections, and terminal outputs are broadcasted with sub-20 millisecond latency.</p><p>Fourth, for security, we use Redis to maintain a real-time JWT token blacklist that guarantees immediate session invalidation on logout.</p><p>Finally, the suite includes an enterprise messaging and video application powered by Tencent Cloud TRTC, using custom HMAC SHA-256 signature generators in <code>chat-app-main/server</code> for encrypted communication.&quot;</p>',11)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
